-- Backup generated on 2026-10-25 20:33:38

CREATE OR REPLACE FUNCTION public.fn_get_platform_order_queue(p_status_filter character varying DEFAULT NULL::character varying)  RETURNS TABLE(id uuid, order_number character varying, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, planned_experience_id uuid, requesting_user_id uuid, requesting_user_email character varying, order_type character varying, workflow_status character varying, payment_status character varying, fulfilment_status character varying, total_purchase_amount numeric, total_rental_fee numeric, total_deposit numeric, shipping_fee numeric, tax_amount numeric, total_amount numeric, currency character varying, quotation_notes text, quotation_valid_until timestamp with time zone, rejection_reason text, cancellation_reason text, delivery_address text, delivery_contact_name character varying, delivery_contact_phone character varying, required_delivery_date timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, organization_name character varying, branch_name character varying, classroom_name character varying, planned_experience_title character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          o.id, o.order_number, o.tenant_id, o.organization_id, o.branch_id, o.classroom_id,         o.planned_experience_id, o.requesting_user_id, o.requesting_user_email,         o.order_type, o.workflow_status, o.payment_status, o.fulfilment_status,         o.total_purchase_amount, o.total_rental_fee, o.total_deposit, o.shipping_fee,         o.tax_amount, o.total_amount, o.currency, o.quotation_notes, o.quotation_valid_until,         o.rejection_reason, o.cancellation_reason, o.delivery_address, o.delivery_contact_name,         o.delivery_contact_phone, o.required_delivery_date, o.created_at, o.updated_at,         org.name AS organization_name, b.name AS branch_name, c.name AS classroom_name,         e.title AS planned_experience_title     FROM material_orders o     JOIN organizations org ON o.organization_id = org.id     LEFT JOIN branches b ON o.branch_id = b.id     LEFT JOIN classrooms c ON o.classroom_id = c.id     LEFT JOIN experiences e ON o.planned_experience_id = e.id     WHERE (p_status_filter IS NULL OR p_status_filter = 'All' OR o.workflow_status = p_status_filter)     ORDER BY o.created_at DESC; $function$ ;
